INSERT INTO "pages" ("id", "title", "content", "slug") VALUES (1, 'About', 'Ordinarium is a liturgy planning workspace that incorporates the structure and rubrics of the ACNA 2019 Book of Common Prayer, enabling clergy and liturgists to assemble, order, and manage liturgical orders of service. It supports the selection of propers, readings, prayers, and ceremonial elements; their arrangement into a coherent liturgy; and export or sharing for use in planning, presentation, or printed materials.\n\nThanks to <a href="https://liturgical-calendar.com" target="_blank">liturgical-calendar.com</a> for church calendar data and logic.\n\n*The Rev. Ryan Willers*\n\nP.S. You can also find collects and other prayers from the *Book of Common Prayer*, the Anglican tradition, and the broader Church at <a href="https://occasionalprayers.com" target="_blank">Occasional Prayers</a>.', 'about');
INSERT INTO "pages" ("id", "title", "content", "slug") VALUES (2, 'Welcome to Ordinarium', 'Ordinarium is a liturgy planning workspace supporting the assembly, ordering, and management of liturgical orders of service. We currently support the eucharistic services from the <a href="https://anglicanchurch.net/" target="_blank">Anglican Church in North America</a> *Book of Common Prayer* (2019).\n\n<a href="/services" class="button">Manage services</a>', 'home');
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (1, 'proper_preface', 'season', 'Christmastide', 'Because you gave Jesus Christ, your only Son, to be born for us; who, by the Holy Spirit and the Virgin Mary his mother, was made truly man, yet without the stain of sin, that we might be cleansed from sin and given the right to become your children.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (2, 'proper_preface', 'day', 'The Lord’s Day', 'Through Jesus Christ our Lord, who on the first day of the week overcame death and the grave, and by his glorious resurrection opened to us the way of everlasting life.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (3, 'proper_preface', 'other', 'At Any Time', 'Through Jesus Christ our Lord; for he is your living Word from before time and for all ages; by him you created all things, and by him you make all things new.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (4, 'proper_preface', 'other', 'At Any Time', 'For you are the source of light and life; you made us in your image, and called us to new life in Jesus Christ our Lord.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (5, 'proper_preface', 'season', 'Advent', 'Because you sent your beloved Son to redeem us from sin and death, and to make us heirs in him of everlasting life; that when he shall come again in power and great glory to judge the world, we may without shame or fear rejoice to behold his appearing.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (6, 'proper_preface', 'season', 'Epiphany', 'Through Jesus Christ our Lord, who took on our mortal flesh to reveal his glory; that he might bring us out of darkness and into his own glorious light.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (7, 'proper_preface', 'season', 'Presentation, Annunciation, and Transfiguration', 'Because in the mystery of the Word made flesh, you have caused a new light to shine in our hearts, to give the knowledge of your glory in the face of your Son Jesus Christ our Lord.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (8, 'proper_preface', 'season', 'Lent', 'You bid your faithful people cleanse their hearts, and prepare with joy for the Paschal feast; that, fervent in prayer and in works of mercy, and renewed by your Word and Sacraments, they may come to the fullness of grace which you have prepared for those who love you.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (9, 'proper_preface', 'season', 'Holy Week', 'Through Jesus Christ our Lord. For our sins he was lifted high upon the Cross, that he might draw the whole world to himself; and by his suffering and death he became the author of eternal salvation for all who put their trust in him.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (10, 'proper_preface', 'season', 'Maundy Thursday', 'Through Jesus Christ our Lord. Having loved his own who were in the world, he loved them to the end; and on the night before he suffered, he instituted these holy mysteries; that we, receiving the benefits of his passion and resurrection, might be made partakers of his divine nature.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (11, 'proper_preface', 'season', 'Easter', 'But chiefly are we bound to praise you for the glorious resurrection of your Son Jesus Christ our Lord; for he is the true Paschal Lamb, who was offered for us, and has taken away the sin of the world; who by his death has destroyed death, and by his rising to life again has won for us everlasting life.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (12, 'proper_preface', 'season', 'Ascension', 'Through your dearly beloved Son Jesus Christ our Lord, who after his most glorious resurrection appeared to his Apostles, and in their sight ascended into heaven to prepare a place for us; that where he is, there we might also ascend, and reign with him in glory.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (13, 'proper_preface', 'season', 'Pentecost', 'Through Jesus Christ our Lord; according to whose most true promise, the Holy Spirit came down from heaven, lighting upon the disciples, to teach them and to lead them into all truth, giving them boldness and fervent zeal constantly to preach the Gospel to all nations; by which we have been brought out of darkness and error into the clear light and true knowledge of you, and of your Son Jesus Christ.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (14, 'proper_preface', 'season', 'Trinity Sunday', 'Who, with your co-eternal Son and Holy Spirit, are one God, one Lord, in Trinity of Persons and in Unity of Substance. For that which we believe of your glory, O Father, we believe the same of your Son, and of the Holy Spirit, without any difference or inequality.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (15, 'proper_preface', 'season', 'All Saints’', 'For in the multitude of your saints, you have surrounded us with so great a cloud of witnesses that we, rejoicing in their fellowship, may run with patience the race that is set before us, and, together with them, may receive the unfading crown of glory.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (16, 'proper_preface', 'season', 'Christ the King', 'Through your only begotten Son Jesus Christ, the King of kings and Lord of lords; for you have seated him at your right hand in glory, and put all things in subjection under his feet, that he may present them to you, O Father, perfectly restored in beauty, truth, and love.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (17, 'proper_preface', 'occasion', 'Apostles and Ordinations', 'Through the great shepherd of your flock, Jesus Christ our Lord, who after his resurrection sent forth his apostles to preach the Gospel and to teach all nations, and promised to be with them always, even to the end of the ages.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (18, 'proper_preface', 'occasion', 'Dedication of a Church', 'Through Jesus Christ our great High Priest, in whom we are built up as living stones of a holy temple, that we might offer before you a sacrifice of praise and thanksgiving which is holy and pleasing in your sight.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (19, 'proper_preface', 'occasion', 'Baptism', 'Because in Jesus Christ our Lord, you have received us as your sons and daughters, made us citizens of your kingdom, and given us the Holy Spirit to guide us into all truth.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (20, 'proper_preface', 'occasion', 'Holy Matrimony', 'Because in the love of wife and husband, you have given us an image of the heavenly Jerusalem, adorned as a bride for her bridegroom, your Son Jesus Christ our Lord; who loves her and gave himself for her, that he might make the whole creation new.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (21, 'proper_preface', 'occasion', 'Burial or Commemoration of the Faithful Departed', 'Through Jesus Christ our Lord, who rose victorious from the dead and comforts us with the blessed hope of everlasting life. For to your faithful people, O Lord, life is changed, not ended; and when our mortal body lies in death, there is prepared for us a dwelling place eternal in the heavens.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (22, 'proper_preface', 'occasion', 'Penitential Occasions', 'Through Jesus Christ our Lord, who was tempted in every way as we are, yet did not sin. By his grace we are able to triumph over every evil, and to live no longer for ourselves alone, but for him who died for us and rose again.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (23, 'proper_preface', 'occasion', 'Rogation Days or Thanksgiving Day', 'Because the wonders of your Creation reflect your goodness and beauty; and your gifts of sun and rain, seed-time and harvest, manifest your constant love and care for all that you have made.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (24, 'proper_preface', 'occasion', 'Canada Day or Independence Day', 'Because you have made us in your image, that we might serve you on earth in freedom, justice, and peace; and have given us the hope of our eternal citizenship with you in your heavenly kingdom.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (25, 'proper_preface', 'occasion', 'Remembrance Day or Memorial Day', 'For by the sacrifice of your Son on the Cross, all who turn to him in the tribulation of war will find their peace with him in paradise.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (26, 'proper_preface', 'common', 'Common of a Martyr', 'For the witness of your martyrs, who took up their cross and followed you even unto death, and revealed your power made perfect in human weakness.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (27, 'proper_preface', 'common', 'Common of a Missionary or Evangelist', 'For the gifts of your Holy Spirit poured out upon prophets and evangelists, to proclaim the Gospel to the ends of the earth, and to bring all peoples under the reign of Jesus Christ our Lord.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (28, 'proper_preface', 'common', 'Common of a Pastor', 'Through Jesus Christ, the great shepherd of the sheep; in him you call faithful pastors and anoint them with your Holy Spirit, to feed your flock by Word and Sacrament, and to lead them in the way of everlasting life.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (29, 'proper_preface', 'common', 'Common of a Teacher of the Faith', 'For you have imparted gifts of wisdom and knowledge to those who teach the Gospel in word and deed, to build up the body of Christ, until we all attain to the unity of the faith and of the knowledge of the Son of God.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (30, 'proper_preface', 'common', 'Common of a Monastic or Religious', 'For calling to the consecrated life those who leave everything for the sake of your kingdom, and who show forth in this world an anticipation of the abundant life you promise in the age to come.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (31, 'proper_preface', 'common', 'Common of an Ecumenist', 'Through your Son Jesus Christ our Lord; in him you bring us to the knowledge of your truth, and unite us by the bond of one Faith and one Baptism, that we might love one another and manifest your love to the world.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (32, 'proper_preface', 'common', 'Common of a Renewer of Society', 'For you never turn away from us, and continually send among us those who seek justice, defend the oppressed, feed the poor, and bind up the brokenhearted.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (33, 'proper_preface', 'common', 'Common of a Reformer of the Church', 'For you, the master builder, never abandon your Church, which you have built of living stones; you call your faithful servants to restore its ancient walls and reunite its broken ramparts, that it may be a holy temple of your presence.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (34, 'proper_preface', 'common', 'Common of any Commemoration', 'For the grace and virtue manifest in [N. and all] your saints, who have been the chosen vessels of your love, and the lights of the world in their generations.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (35, 'acclamation', 'other', 'At Any Time', '*&nbsp;* Blessed be God: the Father, the Son, and the Holy Spirit.  
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (36, 'acclamation', 'season', 'Advent', '*&nbsp;* Surely the Lord is coming soon.  
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (37, 'acclamation', 'season', 'Christmastide', '*&nbsp;* For unto us a child is born,  
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (38, 'acclamation', 'season', 'Feast of the Presentation of Christ', '*&nbsp;* For unto us a child is born,  
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (39, 'acclamation', 'season', 'Epiphanytide', '*&nbsp;* I will make you as a light for the nations,  
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (40, 'acclamation', 'season', 'Lent', '*&nbsp;* Bless the Lord who forgives all our sins.  
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (41, 'acclamation', 'occasion', 'Penitential Occasions', '*&nbsp;* Bless the Lord who forgives all our sins.  
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (42, 'acclamation', 'season', 'Holy Week', '*&nbsp;* Blessed be our God.  
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (43, 'acclamation', 'season', 'Easter', '*&nbsp;* Alleluia! Christ is risen!  
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (44, 'acclamation', 'season', 'Pentecost', '*&nbsp;* The Lord will pour out his Spirit upon all flesh,  
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (45, 'acclamation', 'occasion', 'Occasions of Confirmation and Ordination', '*&nbsp;* The Lord will pour out his Spirit upon all flesh,  
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (46, 'acclamation', 'season', 'All Saints’ Day', '*&nbsp;* Worthy is the Lord our God,  
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (47, 'acclamation', 'occasion', 'Other Appropriate Occasions', '*&nbsp;* Worthy is the Lord our God,  
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (48, 'offertory_sentence', NULL, NULL, 'Remember the words of the Lord Jesus, how he himself said, “It is more blessed to give than to receive.”
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (49, 'offertory_sentence', NULL, NULL, 'Let your light shine before others, so that they may see your good works and give glory to your Father who is in heaven.
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (50, 'offertory_sentence', NULL, NULL, 'Do not lay up for yourselves treasures on earth, where moth and rust destroy and where thieves break in and steal, but lay up for yourselves treasures in heaven, where neither moth nor rust destroys and where thieves do not break in and steal. For where your treasure is, there your heart will be also.
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (51, 'offertory_sentence', NULL, NULL, 'Not everyone who says to me, “Lord, Lord,” will enter the kingdom of heaven, but the one who does the will of my Father who is in heaven.
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (52, 'offertory_sentence', NULL, NULL, 'Whoever sows sparingly will also reap sparingly, and whoever sows bountifully will also reap bountifully. Each one must give as he has decided in his heart, not reluctantly or under compulsion, for God loves a cheerful giver.
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (53, 'offertory_sentence', NULL, NULL, 'As we have opportunity, let us do good to everyone, and especially to those who are of the household of faith.
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (54, 'offertory_sentence', NULL, NULL, 'For God is not unjust so as to overlook your work and the love that you have shown for his name in serving the saints, as you still do.
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (55, 'offertory_sentence', NULL, NULL, 'Do not neglect to do good and to share what you have, for such sacrifices are pleasing to God.
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (56, 'offertory_sentence', NULL, NULL, 'If anyone has the world’s goods and sees his brother in need, yet closes his heart against him, how does God’s love abide in him?
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (57, 'offertory_sentence', NULL, NULL, 'If you have many possessions, make your gift from them in proportion; if few, do not be afraid to give according to the little you have. So you will be laying up a good treasure for yourself against the day of necessity.
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (58, 'offertory_sentence', NULL, NULL, 'And the King will answer them, “Truly, I say to you, as you did it to one of the least of these my brothers, you did it to me.”
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (59, 'offertory_sentence', NULL, NULL, 'How then will they call on him in whom they have not believed? And how are they to believe in him of whom they have never heard? And how are they to hear without someone preaching? And how are they to preach unless they are sent?
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (60, 'offertory_sentence', NULL, NULL, 'And Jesus said to them, “The harvest is plentiful, but the laborers are few. Therefore pray earnestly to the Lord of the harvest to send out laborers into his harvest.”
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (61, 'offertory_sentence', NULL, NULL, 'They shall not appear before the LORD empty-handed. Every man shall give as he is able, according to the blessing of the LORD your God that he has given you.
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (62, 'offertory_sentence', NULL, NULL, 'Offer unto God a sacrifice of thanksgiving, and pay your vows unto the Most High.
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (63, 'offertory_sentence', NULL, NULL, 'Ascribe unto the LORD the honor due unto his Name; bring offerings and come into his courts.
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (64, 'offertory_sentence', NULL, NULL, 'Walk in love, as Christ loved us and gave himself up for us, a fragrant offering and sacrifice to God.
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (65, 'offertory_sentence', NULL, NULL, 'I appeal to you therefore, brothers and sisters, by the mercies of God, to present your bodies as a living sacrifice, holy and acceptable to God, which is your spiritual worship.
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (66, 'offertory_sentence', NULL, NULL, 'For you know the grace of our Lord Jesus Christ, that though he was rich, yet for your sake he became poor, so that you by his poverty might become rich.
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (67, 'offertory_sentence', NULL, NULL, 'You are a chosen race, a royal priesthood, a holy nation, a people for his own possession, that you may proclaim the excellencies of him who called you out of darkness into his marvelous light.
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (68, 'ordinarium', 'rite', 'Renewed Ancient Text', '*The People standing, the Celebrant says*
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (69, 'ordinarium', 'rite', 'Renewed Ancient Text', '*The Celebrant prays (and the People may be invited to join)*
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (70, 'ordinarium', 'rite', 'Renewed Ancient Text', '*Then follows the Summary of the Law, or The Decalogue (page 100).*
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (71, 'ordinarium', 'rite', 'Renewed Ancient Text', '*The Celebrant and People pray*
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (72, 'ordinarium', 'rite', 'Renewed Ancient Text', 'Holy God,  
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (73, 'ordinarium', 'rite', 'Renewed Ancient Text', '*The Gloria or some other song of praise may be sung or said, all standing. It is appropriate to omit the song of praise during penitential seasons and days appointed for fasting.*
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (74, 'ordinarium', 'rite', 'Renewed Ancient Text', '*The Celebrant says to the People*
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (75, 'ordinarium', 'rite', 'Renewed Ancient Text', '*One or more Lessons, as appointed, are read, the Reader first saying*
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (76, 'ordinarium', 'rite', 'Renewed Ancient Text', '*A psalm, hymn, or anthem may follow each reading.*
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (77, 'ordinarium', 'rite', 'Renewed Ancient Text', '*One or more Lessons, as appointed, are read, the Reader first saying*
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (78, 'ordinarium', 'rite', 'Renewed Ancient Text', '*All standing, the Deacon or Priest reads the Gospel, first saying*
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (79, 'ordinarium', 'rite', 'Renewed Ancient Text', NULL, 'The Sermon', 120, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (80, 'ordinarium', 'rite', 'Renewed Ancient Text', '*On Sundays, other Major Feast Days, and other times as appointed, all stand to recite the Nicene Creed, the Celebrant first saying*
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (81, 'ordinarium', 'rite', 'Renewed Ancient Text', '*The Deacon or other person appointed says these prayers, or the Prayers of the People in the Anglican Standard Text. The reader pauses after each bidding, and the people may add petitions, either silently or aloud.*
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (82, 'ordinarium', 'rite', 'Renewed Ancient Text', '*The Deacon or other person appointed says the following*
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (83, 'ordinarium', 'rite', 'Renewed Ancient Text', '*The Celebrant may then say one or more of the following sentences, first saying*
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (84, 'ordinarium', 'rite', 'Renewed Ancient Text', '*Celebrant* The Peace of the Lord be always with you.  
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (85, 'ordinarium', 'rite', 'Renewed Ancient Text', '*The Celebrant may begin the Offertory with one of the provided sentences of Scripture.*
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (86, 'ordinarium', 'rite', 'Renewed Ancient Text', '*The People remain standing. The Celebrant faces them and sings or says*
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (87, 'ordinarium', 'rite', 'Renewed Ancient Text', '*Celebrant and People*
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (88, 'ordinarium', 'rite', 'Renewed Ancient Text', '*The People stand or kneel. The Celebrant continues*
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (89, 'ordinarium', 'rite', 'Renewed Ancient Text', '*The Celebrant then says*
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (90, 'ordinarium', 'rite', 'Renewed Ancient Text', '*If the consecrated Bread was not broken earlier, the Celebrant breaks it now.*
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (91, 'ordinarium', 'rite', 'Renewed Ancient Text', '*Celebrant and People together may say*
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (92, 'ordinarium', 'rite', 'Renewed Ancient Text', '*The following or some other suitable anthem may be sung or said here*
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (93, 'ordinarium', 'rite', 'Renewed Ancient Text', '*Facing the People, the Celebrant may say the following invitation*
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (94, 'ordinarium', 'rite', 'Renewed Ancient Text', '*After Communion, the Celebrant says*
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (95, 'ordinarium', 'rite', 'Renewed Ancient Text', '*The Bishop when present, or the Priest, gives this or an alternate blessing*
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (96, 'ordinarium', 'rite', 'Renewed Ancient Text', '*The Deacon, or the Priest, may dismiss the People with these words*
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (97, 'collect', 'proper', 'AdventI', 'Almighty God, give us grace to cast away the works of darkness, and put on the armor of light, now in the time of this mortal life in which your Son Jesus Christ came to visit us in great humility; that in the last day, when he shall come again in his glorious majesty to judge both the living and the dead, we may rise to the life immortal; through him who lives and reigns with you and the Holy Spirit, one God, now and for ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (98, 'collect', 'proper', 'AdventII', 'Blessed Lord, who caused all holy Scriptures to be written for our learning: Grant us so to hear them, read, mark, learn, and inwardly digest them, that by patience and the comfort of your holy Word we may embrace and ever hold fast the blessed hope of everlasting life, which you have given us in our Savior Jesus Christ; who lives and reigns with you and the Holy Spirit, one God, for ever and ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (99, 'collect', 'proper', 'AdventIII', 'O Lord Jesus Christ, you sent your messengers the prophets to preach repentance and prepare the way for our salvation: Grant that the ministers and stewards of your mysteries may likewise make ready your way, by turning the hearts of the disobedient toward the wisdom of the just, that at your second coming to judge the world, we may be found a people acceptable in your sight; for with the Father and the Holy Spirit you live and reign, one God, now and for ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (100, 'collect', 'proper', 'AdventIV', 'Stir up your power, O Lord, and with great might come among us; and as we are sorely hindered by our sins from running the race that is set before us, let your bountiful grace and mercy speedily help and deliver us; through Jesus Christ our Lord, to whom, with you and the Holy Spirit, be honor and glory, now and for ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (101, 'collect', 'proper', 'ChristmasEve', 'O God, you have caused this holy night to shine with the brightness of the true Light: Grant that we, who have known the mystery of that Light on earth, may also enjoy him perfectly in heaven; where with you and the Holy Spirit he lives and reigns, one God, in glory everlasting. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (102, 'collect', 'proper', 'Christmas', 'Almighty God, you have given your only-begotten Son to take our nature upon him, and to be born \\[this day\\] of a pure virgin: Grant that we, who have been born again and made your children by adoption and grace, may daily be renewed by your Holy Spirit; through Jesus Christ our Lord, to whom with you and the same Spirit be honor and glory, now and for ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (103, 'collect', 'proper', 'ChristmasI', 'Almighty God, you have poured upon us the new light of your incarnate Word: Grant that this light, kindled in our hearts, may shine forth in our lives; through Jesus Christ our Lord, who lives and reigns with you in the unity of the Holy Spirit, one God, now and for ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (104, 'collect', 'proper', 'ChristmasII', 'O God, who wonderfully created, and yet more wonderfully restored, the dignity of human nature: Grant that we may share the divine life of him who humbled himself to share our humanity, your Son Jesus Christ our Lord; who lives and reigns with you, in the unity of the Holy Spirit, one God, for ever and ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (105, 'collect', 'proper', 'Epiphany', 'O God, by the leading of a star you manifested your only Son to the peoples of the earth: Lead us, who know you now by faith, to your presence, where we may see your glory face to face; through Jesus Christ our Lord, who lives and reigns with you and the Holy Spirit, one God, now and for ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (106, 'collect', 'proper', 'EpiphanyI', 'Eternal Father, at the baptism of Jesus you revealed him to be your Son, and your Holy Spirit descended upon him like a dove: Grant that we, who are born again by water and the Spirit, may be faithful as your adopted children; through Jesus Christ our Lord, who lives and reigns with you and the Holy Spirit, one God, now and for ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (107, 'collect', 'proper', 'EpiphanyII', 'Almighty God, whose Son our Savior Jesus Christ is the light of the world: Grant that your people, illumined by your Word and Sacraments, may shine with the radiance of Christ’s glory, that he may be known, worshiped, and obeyed to the ends of the earth; through Jesus Christ our Lord, who with you and the Holy Spirit lives and reigns, one God, now and for ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (108, 'collect', 'proper', 'EpiphanyIII', 'Give us grace, O Lord, to answer readily the call of our Savior Jesus Christ and proclaim to all people the Good News of his salvation, that we and the whole world may perceive the glory of his marvelous works; who lives and reigns with you and the Holy Spirit, one God, for ever and ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (109, 'collect', 'proper', 'EpiphanyIV', 'O God, you know that we are set in the midst of many grave dangers, and because of the frailty of our nature we cannot always stand upright: Grant that your strength and protection may support us in all dangers and carry us through every temptation; through Jesus Christ our Lord, who lives and reigns with you and the Holy Spirit, one God, for ever and ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (110, 'collect', 'proper', 'EpiphanyV', 'O Lord, our heavenly Father, keep your household the Church continually in your true religion, that we who trust in the hope of your heavenly grace may always be defended by your mighty power; through Jesus Christ our Lord, who lives and reigns with you and the Holy Spirit, now and for ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (111, 'collect', 'proper', 'EpiphanyVI', 'Almighty God, look mercifully upon your people, that by your great goodness they may be governed and preserved evermore; through Jesus Christ our Lord, who lives and reigns with you and the Holy Spirit, now and for ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (112, 'collect', 'proper', 'EpiphanyVII', 'O God, the strength of all who put their trust in you: mercifully accept our prayers, and because, through the weakness of our mortal nature, we can do no good thing without you, grant us the help of your grace, that in keeping your commandments we may please you both in will and deed; through Jesus Christ our Lord, who lives and reigns with you and the Holy Spirit, one God, for ever and ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (113, 'collect', 'proper', 'EpiphanyVIII', 'Almighty and merciful God, in your goodness keep us, we pray, from all things that may hurt us; that we, being ready both in mind and body, may accomplish with joyful hearts those things which belong to your purpose; through Jesus Christ our Lord, who lives and reigns with you and the Holy Spirit, one God, now and for ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (114, 'collect', 'proper', 'EpiphanyPaenultima', 'Almighty God, through the outpouring of the Holy Spirit, you revealed the way of eternal life to every race and nation: Pour out this gift anew, that by the preaching of the Gospel your salvation may reach to the ends of the earth; through Jesus Christ our Lord, who lives and reigns with you, in the unity of the Holy Spirit, one God, for ever and ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (115, 'collect', 'proper', 'EpiphanyUltima', 'O God, who before the passion of your only-begotten Son revealed his glory upon the holy mountain: Grant that we, beholding by faith the light of his countenance, may be strengthened to bear our cross, and be changed into his likeness from glory to glory; through Jesus Christ our Lord, who lives and reigns with you and the Holy Spirit, one God, for ever and ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (116, 'collect', 'proper', 'AshWednesday', 'Almighty and everlasting God, you hate nothing you have made, and you forgive the sins of all who are penitent: Create and make in us new and contrite hearts, that we, worthily lamenting our sins and acknowledging our wretchedness, may obtain of you, the God of all mercy, perfect remission and forgiveness; through Jesus Christ our Lord, who lives and reigns with you and the Holy Spirit, one God, for ever and ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (117, 'collect', 'proper', 'LentI', 'Almighty God, whose blessed Son was led by the Spirit to be tempted by Satan: Come quickly to help us who are assaulted by many temptations, and, as you know the weaknesses of each of us, let each one find you mighty to save; through Jesus Christ your Son our Lord, who lives and reigns with you and the Holy Spirit, one God, now and for ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (118, 'collect', 'proper', 'LentII', 'Almighty God, you know that we have no power in ourselves to help ourselves: Keep us both outwardly in our bodies and inwardly in our souls, that we may be defended from all adversities that may happen to the body, and from all evil thoughts that may assault and hurt the soul; through Jesus Christ our Lord, who lives and reigns with you and the Holy Spirit, one God, for ever and ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (119, 'collect', 'proper', 'LentIII', 'Heavenly Father, you have made us for yourself, and our hearts are restless until they rest in you: Look with compassion upon the heartfelt desires of your servants, and purify our disordered affections, that we may behold your eternal glory in the face of Christ Jesus; who lives and reigns with you and the Holy Spirit, one God, for ever and ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (120, 'collect', 'proper', 'LentIV', 'Gracious Father, whose blessed Son Jesus Christ came down from heaven to be the true bread which gives life to the world: Evermore give us this bread, that he may live in us, and we in him; who lives and reigns with you and the Holy Spirit, one God, now and for ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (121, 'collect', 'proper', 'LentV', 'Almighty God, you alone can bring into order the unruly wills and affections of sinners: Grant your people grace to love what you command and desire what you promise; that, among the swift and varied changes of this world, our hearts may surely there be fixed where true joys are to be found; through Jesus Christ our Lord, who lives and reigns with you and the Holy Spirit, one God, now and for ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (122, 'collect', 'proper', 'PalmSunday', 'Almighty and everlasting God, in your tender love for us you sent your Son our Savior Jesus Christ to take upon himself our nature, and to suffer death upon the cross, giving us the example of his great humility: Mercifully grant that we may walk in the way of his suffering, and come to share in his resurrection; through Jesus Christ our Lord, who lives and reigns with you and the Holy Spirit, one God, for ever and ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (123, 'collect', 'proper', 'HolyMonday', 'Almighty God, whose most dear Son went not up to joy but first he suffered pain, and entered not into glory before he was crucified: Mercifully grant that we, walking in the way of the cross, may find it none other than the way of life and peace; through Jesus Christ our Lord, who lives and reigns with you and the Holy Spirit, one God, for ever and ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (124, 'collect', 'proper', 'HolyTuesday', 'O Lord our God, whose blessed Son gave his back to be whipped and did not hide his face from shame and spitting: Give us grace to accept joyfully the sufferings of the present time, confident of the glory that shall be revealed; through Jesus Christ our Lord, who lives and reigns with you and the Holy Spirit, one God, for ever and ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (125, 'collect', 'proper', 'HolyWednesday', 'Assist us mercifully with your grace, Lord God of our salvation, that we may enter with joy upon the meditation of those mighty acts by which you have promised us life and immortality; through Jesus Christ our Lord, who lives and reigns with you and the Holy Spirit, one God, for ever and ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (126, 'collect', 'proper', 'MaundyThursday', 'Almighty Father, whose most dear Son, on the night before he suffered, instituted the Sacrament of his Body and Blood: Mercifully grant that we may receive it in thankful remembrance of Jesus Christ our Savior, who in these holy mysteries gives us a pledge of eternal life; and who lives and reigns with you and the Holy Spirit, one God, for ever and ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (127, 'collect', 'proper', 'GoodFriday', 'Almighty God, we beseech you graciously to behold this your family, for whom our Lord Jesus Christ was willing to be betrayed and given into the hands of sinners, and to suffer death upon the cross; who now lives and reigns with you and the Holy Spirit, one God, for ever and ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (128, 'collect', 'proper', 'HolySaturday', 'O God, Creator of heaven and earth: Grant that, as the crucified body of your dear Son was laid in the tomb and rested on this holy Sabbath, so we may await with him the coming of the third day, and rise with him to newness of life; through Jesus Christ our Lord. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (129, 'collect', 'proper', 'HolySaturday', 'O God of the living, on this day your Son our Savior descended to the place of the dead: Look with kindness on all of us who wait in hope for liberation from the corruption of sin and death, and give us a share in the glory of the children of God; through Jesus Christ your Son our Lord. **Amen.**', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (130, 'collect', 'proper', 'EasterEve', 'O God, you made this most holy night to shine with the glory of the Lord’s resurrection: Stir up in your Church that Spirit of adoption which is given to us in Baptism, that we, being renewed both in body and mind, may worship you in sincerity and truth; through Jesus Christ our Lord, who lives and reigns with you, in the unity of the Holy Spirit, one God, now and for ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (131, 'collect', 'proper', 'Easter', 'Almighty God, who through your only-begotten Son Jesus Christ overcame death and opened to us the gate of everlasting life: Grant that we, who celebrate with joy the day of the Lord’s resurrection, may, by your life-giving Spirit, be delivered from sin and raised from death; through Jesus Christ our Lord, who lives and reigns with you and the Holy Spirit, one God, now and for ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (132, 'collect', 'proper', 'Easter', 'O God, who for our redemption gave your only begotten Son to die upon the cross, and by his glorious resurrection delivered us from the devil and the power of death: Grant us grace to die daily to sin, that we may live with him in the joy of his resurrection; who lives and reigns with you and the Holy Spirit, now and for ever. **Amen.**', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (133, 'collect', 'proper', 'EasterMonday', 'Grant, we pray, Almighty God, that we who celebrate with reverence the Paschal feast may be made worthy to attain to everlasting joys; through Jesus Christ our Lord, who lives and reigns with you and the Holy Spirit, one God, now and for ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (134, 'collect', 'proper', 'EasterTuesday', 'O God, who by the glorious resurrection of your Son Jesus Christ destroyed death and brought life and immortality to light: Grant that we, who have been raised with him, may abide in his presence and rejoice in the hope of eternal glory; through Jesus Christ our Lord, to whom, with you and the Holy Spirit, be honor and glory, now and for ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (135, 'collect', 'proper', 'EasterWednesday', 'O God, whose blessed Son made himself known to his disciples in the breaking of bread: Open the eyes of our faith, that we may behold him in the fullness of his redeeming work; who lives and reigns with you, in the unity of the Holy Spirit, one God, now and for ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (136, 'collect', 'proper', 'EasterThursday', 'Almighty God, you show those in error the light of your truth so that they may turn to the path of righteousness: Grant that all who have been reborn into the fellowship of Christ’s Body may show forth in their lives what they profess by their faith; through Jesus Christ our Lord, who lives and reigns with you and the Holy Spirit, one God, now and for ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (137, 'collect', 'proper', 'EasterFriday', 'Almighty Father, who gave your only Son to die for our sins and to rise for our justification: Give us grace so to put away the leaven of malice and wickedness, that we may always serve you in purity of life; through Jesus Christ your Son our Lord, who lives and reigns with you and the Holy Spirit, one God, now and for ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (138, 'collect', 'proper', 'EasterSaturday', 'Heavenly Father, you have delivered us from the dominion of sin and death, and brought us into the kingdom of your beloved Son: Grant that, as by his death he has called us to life, so by his love he may raise us to eternal joys; who lives and reigns with you, in the unity of the Holy Spirit, one God, now and for ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (139, 'collect', 'proper', 'EasterII', 'Almighty and everlasting God, who in the Paschal mystery established the new covenant of reconciliation: Grant that all who have been reborn into the fellowship of Christ’s Body may show forth in their lives what they profess by their faith; through Jesus Christ our Lord, who lives and reigns with you and the Holy Spirit, one God, for ever and ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (140, 'collect', 'proper', 'EasterIII', 'Almighty God, you gave your only Son to be for us both a sacrifice for sin and an example of godly living: Give us grace thankfully to receive his inestimable benefits, and daily to follow the blessed steps of his most holy life; through Jesus Christ our Lord, who lives and reigns with you and the Holy Spirit, one God, for ever and ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (141, 'collect', 'proper', 'EasterIV', 'O God, whose Son Jesus Christ is the Good Shepherd of your people: Grant that, when we hear his voice, we may know him who calls us each by name, and follow where he leads; who, with you and the Holy Spirit, lives and reigns, one God, for ever and ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (142, 'collect', 'proper', 'EasterV', 'Almighty God, whom truly to know is everlasting life: Grant us so perfectly to know your Son Jesus Christ to be the way, the truth, and the life, that we may steadfastly follow his steps in the way that leads to eternal glory; through Jesus Christ your Son our Lord, who lives and reigns with you, in the unity of the Holy Spirit, one God, for ever and ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (143, 'collect', 'proper', 'EasterVI', 'O God, you have prepared for those who love you such good things as surpass our understanding: Pour into our hearts such love towards you, that we, loving you in all things and above all things, may obtain your promises, which exceed all that we can desire; through Jesus Christ our Lord, who lives and reigns with you and the Holy Spirit, one God, for ever and ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (144, 'collect', 'proper', 'Ascension', 'Almighty God, whose only-begotten Son our Lord Jesus Christ ascended into heaven: May our hearts and minds also there ascend, and with him continually dwell; who lives and reigns with you and the Holy Spirit, one God, for ever and ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (145, 'collect', 'proper', 'EasterVII', 'O God, the King of glory, you have exalted your only Son Jesus Christ with great triumph to your kingdom in heaven: Do not leave us comfortless, but send us your Holy Spirit to strengthen us, and exalt us to that place where our Savior Christ has gone before; who lives and reigns with you and the Holy Spirit, one God, in glory everlasting. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (146, 'collect', 'proper', 'Pentecost', 'Almighty God, on this day, through the outpouring of the Holy Spirit, you revealed the way of eternal life to every race and nation: Pour out this gift anew, that by the preaching of the Gospel your salvation may reach to the ends of the earth; through Jesus Christ our Lord, who lives and reigns with you, in the unity of the Holy Spirit, one God, for ever and ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (147, 'collect', 'proper', 'Pentecost', 'O God, who on this day taught the hearts of your faithful people by sending to them the light of your Holy Spirit: Grant us by the same Spirit to have a right judgment in all things, and evermore to rejoice in his holy comfort; through Jesus Christ your Son our Lord, who lives and reigns with you, in the unity of the Holy Spirit, one God, for ever and ever. **Amen.**', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (148, 'collect', 'proper', 'TrinitySunday', 'Almighty and everlasting God, you have given to us your servants grace, by the confession of a true faith, to acknowledge the glory of the eternal Trinity, and in the power of your divine Majesty to worship the Unity: Keep us steadfast in this faith and worship, and bring us at last to see you in your one and eternal glory, O Father; who with the Son and the Holy Spirit live and reign, one God, for ever and ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (149, 'collect', 'proper', 'Proper1', 'O God, the strength of all who put their trust in you: Mercifully accept our prayers, and because, through the weakness of our mortal nature, we can do no good thing without you, grant us the help of your grace to keep your commandments, that we may please you in will and deed; through Jesus Christ our Lord, who lives and reigns with you and the Holy Spirit, one God, for ever and ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (150, 'collect', 'proper', 'Proper2', 'O Lord, you never fail to support and govern those whom you bring up in your steadfast love and fear: Keep us, we pray, under your continual protection and providence, and give us a perpetual fear and love of your holy Name; through Jesus Christ our Lord, who lives and reigns with you and the Holy Spirit, one God, for ever and ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (151, 'collect', 'proper', 'Proper3', 'O Lord, we entreat you mercifully to hear us, and grant that we, to whom you have given the desire to pray, may by your mighty aid be defended and comforted in all our adversities; through Jesus Christ our Lord, who lives and reigns with you and the Holy Spirit, one God, for ever and ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (152, 'collect', 'proper', 'Proper4', 'O God, the protector of all those who trust in you, without whom nothing is strong, nothing is holy: Increase and multiply upon us your mercy, that, with you as our ruler and guide, we may so pass through things temporal that we lose not the things eternal; grant this, heavenly Father, for the sake of your Son Jesus Christ, who lives and reigns with you and the Holy Spirit, one God, for ever and ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (153, 'collect', 'proper', 'Proper5', 'Grant, O Lord, that the course of this world may be so peaceably ordered by your providence, that your Church may joyfully serve you in quiet confidence and godly peace; through Jesus Christ our Lord, who lives and reigns with you and the Holy Spirit, one God, for ever and ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (154, 'collect', 'proper', 'Proper6', 'O Lord, from whom all good proceeds: Grant us the inspiration of your Holy Spirit, that we may always think those things that are good, and by your merciful guidance may accomplish the same; through Jesus Christ our Lord, who lives and reigns with you and the Holy Spirit, one God, for ever and ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (155, 'collect', 'proper', 'Proper7', 'Lord of all power and might, the author and giver of all good things: Graft in our hearts the love of your Name, increase in us true religion, nourish us with all goodness, and bring forth in us the fruit of good works; through Jesus Christ our Lord, who lives and reigns with you and the Holy Spirit, one God, for ever and ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (156, 'collect', 'proper', 'Proper8', 'O God, your never-failing providence sets in order all things both in heaven and on earth: Put away from us all hurtful things, and give us those things that are profitable for us; through Jesus Christ our Lord, who lives and reigns with you and the Holy Spirit, one God, for ever and ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (157, 'collect', 'proper', 'Proper9', 'Grant us, O Lord, we pray, the spirit to think and do always those things that are right, that we, who can do no good thing apart from you, may by you be enabled to live according to your will; through Jesus Christ our Lord, who lives and reigns with you and the Holy Spirit, one God, for ever and ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (158, 'collect', 'proper', 'Proper10', 'Let your merciful ears, O Lord, be open to the prayers of your humble servants; and, that we may receive what we ask, teach us by your Holy Spirit to ask only those things that are pleasing to you; through Jesus Christ our Lord, who with you and the same Spirit lives and reigns for ever and ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (159, 'collect', 'proper', 'Proper11', 'O God, you declare your almighty power chiefly in showing mercy and pity: Grant us the fullness of your grace, that we, running to obtain your promises, may become partakers of your heavenly treasure; through Jesus Christ our Lord, who lives and reigns with you and the Holy Spirit, one God, for ever and ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (160, 'collect', 'proper', 'Proper12', 'Almighty and everlasting God, you are always more ready to hear than we to pray, and to give more than we either desire or deserve: Pour down upon us the abundance of your mercy, forgiving us those things of which our conscience is afraid, and giving us those good things for which we are not worthy to ask, except through the merits and mediation of Jesus Christ our Savior; who lives and reigns with you and the Holy Spirit, one God, for ever and ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (161, 'collect', 'proper', 'Proper13', 'Almighty and merciful God, it is only by your grace that your faithful people offer you true and laudable service: Grant that we may run without stumbling to obtain your heavenly promises; through Jesus Christ our Lord, who lives and reigns with you and the Holy Spirit, one God, now and for ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (162, 'collect', 'proper', 'Proper14', 'Almighty God, give us the increase of faith, hope, and love; and, that we may obtain what you have promised, make us love what you command; through Jesus Christ our Lord, who lives and reigns with you and the Holy Spirit, one God, for ever and ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (163, 'collect', 'proper', 'Proper15', 'Keep your Church, O Lord, by your perpetual mercy; and because without you the frailty of our nature causes us to fall, keep us from all things hurtful, and lead us to all things profitable for our salvation; through Jesus Christ our Lord, who lives and reigns with you and the Holy Spirit, one God, for ever and ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (164, 'collect', 'proper', 'Proper16', 'Let your continual mercy, O Lord, cleanse and defend your Church; and, because it cannot continue in safety without your help, protect and govern it always by your goodness; through Jesus Christ our Lord, who lives and reigns with you and the Holy Spirit, one God, for ever and ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (165, 'collect', 'proper', 'Proper17', 'O Lord, we pray that your grace may always precede and follow after us, that we may continually be given to good works; through Jesus Christ our Lord, who lives and reigns with you and the Holy Spirit, one God, now and for ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (166, 'collect', 'proper', 'Proper18', 'O Lord God, grant your people grace to withstand the temptations of the world, the flesh, and the devil, and with pure hearts and minds to follow you, the only God; through Jesus Christ our Lord, who lives and reigns with you and the Holy Spirit, one God, now and for ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (167, 'collect', 'proper', 'Proper19', 'O God, because without you we are not able to please you, mercifully grant that your Holy Spirit may in all things direct and rule our hearts; through Jesus Christ our Lord, who lives and reigns with you and the Holy Spirit, one God, now and for ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (168, 'collect', 'proper', 'Proper20', 'O Lord, you have taught us that without love, all our deeds are worth nothing: Send your Holy Spirit and pour into our hearts that most excellent gift of charity, the true bond of peace and of all virtues, without which whoever lives is counted dead before you; grant this for the sake of your Son Jesus Christ, who lives and reigns with you and the Holy Spirit, one God, for ever and ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (169, 'collect', 'proper', 'Proper21', 'O merciful Lord, grant to your faithful people pardon and peace, that we may be cleansed from all our sins and serve you with a quiet mind; through Jesus Christ our Lord, who lives and reigns with you and the Holy Spirit, one God, now and for ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (170, 'collect', 'proper', 'Proper22', 'Keep, O Lord, your household the Church in continual godliness, that through your protection it may be free from all adversities, and devoutly serve you in good works, to the glory of your Name; through Jesus Christ our Lord, who lives and reigns with you and the Holy Spirit, one God, now and for ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (171, 'collect', 'proper', 'Proper23', 'O God, our refuge and strength, true source of all godliness: Graciously hear the devout prayers of your Church, and grant that those things which we ask faithfully, we may obtain effectually; through Jesus Christ our Lord, who lives and reigns with you and the Holy Spirit, one God, now and for ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (172, 'collect', 'proper', 'Proper24', 'Set us free, loving Father, from the bondage of our sins, and in your goodness and mercy give us the liberty of that abundant life which you have made known to us in our Savior Jesus Christ; who lives and reigns with you, in the unity of the Holy Spirit, one God, now and for ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (173, 'collect', 'proper', 'Proper25', 'Almighty and everlasting God, you govern all things both in heaven and on earth: Mercifully hear the supplications of your people, and in our time grant us your peace; through Jesus Christ our Lord, who lives and reigns with you and the Holy Spirit, one God, for ever and ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (174, 'collect', 'proper', 'Proper26', 'Grant us, Lord, not to be anxious about earthly things, but to love things heavenly; and even now, as we live among things that are passing away, to hold fast to those that shall endure; through Jesus Christ our Lord, who lives and reigns with you and the Holy Spirit, one God, for ever and ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (175, 'collect', 'proper', 'Proper27', 'O God, whose blessed Son came into the world that he might destroy the works of the devil and make us children of God and heirs of eternal life: Grant that, having this hope, we may purify ourselves as he is pure; that, when he comes again with power and great glory, we may be made like him in his eternal and glorious kingdom; where he lives and reigns with you and the Holy Spirit, one God, for ever and ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (176, 'collect', 'proper', 'Proper28', 'Stir up, O Lord, the wills of your faithful people, that bringing forth in abundance the fruit of good works, they may be abundantly rewarded when our Savior Jesus Christ comes to restore all things; who lives and reigns with you and the Holy Spirit, one God, for ever and ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (177, 'collect', 'proper', 'Proper29', 'Almighty and everlasting God, whose will it is to restore all things in your well-beloved Son, the King of kings and Lord of lords: Mercifully grant that the peoples of the earth, divided and enslaved by sin, may be freed and brought together under his most gracious rule; who lives and reigns with you and the Holy Spirit, one God, now and for ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (178, 'collect', 'proper', 'Andrew', 'Almighty God, you gave such grace to your apostle Andrew that he readily obeyed the call of your Son Jesus Christ, and brought his brother with him: Give us, who are called by your holy Word, grace to follow him without delay, and to bring those near to us into his gracious presence; who lives and reigns with you and the Holy Spirit, one God, now and for ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (179, 'collect', 'proper', 'Thomas', 'Everliving God, you strengthened your apostle Thomas with firm and certain faith in your Son’s resurrection: Grant us so perfectly and without doubt to believe in Jesus Christ, our Lord and our God, that our faith may never be found wanting in your sight; through him who lives and reigns with you and the Holy Spirit, one God, now and for ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (180, 'collect', 'proper', 'Stephen', 'O Glorious Lord, your servant Stephen looked up to heaven and prayed for his persecutors: grant that in all our sufferings here upon earth we may love and forgive our enemies, looking steadfastly to Jesus Christ our Lord, who sits at your right hand and intercedes for us; and who lives and reigns with you and the Holy Spirit, one God, now and for ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (181, 'collect', 'proper', 'John', 'Shed upon your Church, O Lord, the brightness of your light; that we, being illumined by the teaching of your apostle and evangelist John, may so walk in the light of your truth, that at length we may attain to the fullness of eternal life; through Jesus Christ our Lord, who lives and reigns with you and the Holy Spirit, one God, for ever and ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (182, 'collect', 'proper', 'HolyInnocents', 'Almighty God, out of the mouths of children you manifest your truth, and by the death of the Holy Innocents at the hands of evil tyrants you show your strength in our weakness: We ask you to mortify all that is evil within us, and so strengthen us by your grace, that we may glorify your holy Name by the innocence of our lives and the constancy of our faith even unto death; through Jesus Christ our Lord, who died for us and now lives with you and the Holy Spirit, world without end. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (183, 'collect', 'proper', 'HolyName', 'Almighty God, your blessed Son fulfilled the covenant of circumcision for our sake, and was given the Name that is above every name: Give us grace faithfully to bear his Name, and to worship him with pure hearts according to the New Covenant; who lives and reigns with you, in the unity of the Holy Spirit, one God, now and for ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (184, 'collect', 'proper', 'Peter', 'Almighty Father, who inspired Simon Peter, first among the apostles, to confess Jesus as Messiah and Son of the living God: Keep your Church steadfast upon the rock of this faith, that in unity and peace we may proclaim the one truth and follow the one Lord, our Savior Jesus Christ; who lives and reigns with you and the Holy Spirit, one God, now and for ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (185, 'collect', 'proper', 'Paul', 'O God, by the preaching of your apostle Paul you have caused the light of the Gospel to shine throughout the world: Grant, we pray, that having his wonderful conversion in remembrance, we may show ourselves thankful to you by following his holy teaching; through Jesus Christ our Lord, who lives and reigns with you, in the unity of the Holy Spirit, one God, now and for ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (186, 'collect', 'proper', 'Presentation', 'Almighty and everliving God, we humbly pray that, as your only-begotten Son was this day presented in the temple in the substance of our flesh, so we may be presented to you with pure and clean hearts by Jesus Christ our Lord; who lives and reigns with you and the Holy Spirit, one God, now and for ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (187, 'collect', 'proper', 'Matthias', 'Almighty God, who in the place of Judas chose your faithful servant Matthias to be numbered among the Twelve: Grant that your Church, being delivered from false apostles, may always be guided and governed by faithful and true pastors; through Jesus Christ our Lord, who lives and reigns with you, in the unity of the Holy Spirit, one God, now and for ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (188, 'collect', 'proper', 'Joseph', 'O God, who from the family of your servant David raised up Joseph to be the guardian of your incarnate Son and the husband of his virgin mother: Give us grace to imitate his uprightness of life and his obedience to your commands; through Jesus Christ our Lord, who lives and reigns with you and the Holy Spirit, one God, for ever and ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (189, 'collect', 'proper', 'Annunciation', 'Pour your grace into our hearts, O Lord, that we who have known the incarnation of your Son Jesus Christ, announced by an angel to the Virgin Mary, may by his cross and passion be brought to the glory of his resurrection; who lives and reigns with you, in the unity of the Holy Spirit, one God, now and for ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (190, 'collect', 'proper', 'Mark', 'Almighty God, by the hand of Mark the evangelist you have given to your Church the Gospel of Jesus Christ: We thank you for his witness, and pray that you will give us grace to know the truth, and not to be carried about by every wind of false doctrine, that we may know Jesus Christ as our Lord and Savior; who lives and reigns with you and the Holy Spirit, one God, for ever and ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (191, 'collect', 'proper', 'PhilipJames', 'Almighty God, you gave to your apostles Philip and James the grace and strength to bear witness to Jesus as the way, the truth, and the life: Grant that we, being mindful of their victory of faith, may glorify in life and death the Name of our Lord Jesus Christ; who lives and reigns with you and the Holy Spirit, one God, now and for ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (192, 'collect', 'proper', 'Visitation', 'Almighty God, by whose grace Elizabeth rejoiced with the blessed virgin Mary and greeted her as the mother of the Lord: look with favor on your lowly servants, that, with Mary, we may magnify your holy Name and rejoice to acclaim her Son as our Savior; who lives and reigns with you, in the unity of the Holy Spirit, one God, now and for ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (193, 'collect', 'proper', 'Barnabas', 'Grant, O God, that we may follow the example of your faithful servant Barnabas, who, seeking not his own renown but the well-being of your Church, gave generously of his life and substance for the relief of the poor, and went forth courageously in mission for the spread of the Gospel; through Jesus Christ our Lord, who lives and reigns with you and the Holy Spirit, one God, for ever and ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (194, 'collect', 'proper', 'JohnTheBaptist', 'Almighty God, by whose providence your servant John the Baptist was wonderfully born, and sent to prepare the way of your Son our Savior by preaching repentance: Make us so to follow his teaching and holy life, that we may truly repent, boldly rebuke vice, patiently suffer for the sake of truth, and proclaim the coming of Jesus Christ our Lord; who lives and reigns with you and the Holy Spirit, one God, for ever and ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (195, 'collect', 'proper', 'PeterPaul', 'Almighty God, whose blessed apostles Peter and Paul glorified you by their martyrdom: Grant that your Church, instructed by their teaching and example, and knit together in unity by your Spirit, may ever stand firm upon the one foundation, which is Jesus Christ our Lord; who lives and reigns with you, in the unity of the Holy Spirit, one God, now and for ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (196, 'collect', 'proper', 'MaryMagdalene', 'Almighty God, whose blessed Son restored Mary Magdalene to health of body and of mind, and called her to be a witness of his resurrection: Mercifully grant that, by your grace, we may be healed from all our infirmities and know you in the power of his unending life; who with you and the Holy Spirit lives and reigns, one God, now and for ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (197, 'collect', 'proper', 'James', 'O gracious God, your servant and apostle James was first among the Twelve to suffer martyrdom for the Name of Jesus Christ: Pour out upon the leaders of your Church that spirit of self-denying service, by which they may have true authority among your people; through Jesus Christ our Lord, who lives and reigns with you and the Holy Spirit, one God, now and for ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (198, 'collect', 'proper', 'Transfiguration', 'O God, who on the holy mount revealed to chosen witnesses your well-beloved Son, wonderfully transfigured, in raiment white and glistening: Mercifully grant that we, being delivered from the disquietude of this world, may by faith behold the King in his beauty; who with you and the Holy Spirit lives and reigns, one God, for ever and ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (199, 'collect', 'proper', 'Mary', 'O God, you have taken to yourself the blessed Virgin Mary, mother of your incarnate Son: Grant that we, who have been redeemed by his blood, may share with her the glory of your eternal kingdom; through Jesus Christ our Lord, who lives and reigns with you, in the unity of the Holy Spirit, one God, now and for ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (200, 'collect', 'proper', 'Bartholomew', 'Almighty and everlasting God, you gave your apostle Bartholomew grace truly to believe and to preach your Word: Grant that your Church may love what he believed and preach what he taught; through Jesus Christ our Lord, who lives and reigns with you and the Holy Spirit, one God, for ever and ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (201, 'collect', 'proper', 'HolyCrossDay', 'Almighty God, whose Son our Savior Jesus Christ was lifted high upon the cross that he might draw the whole world to himself: Mercifully grant that we, who glory in the mystery of our redemption, may have grace to take up our cross and follow him; who lives and reigns with you and the Holy Spirit, one God, in glory everlasting. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (202, 'collect', 'proper', 'Matthew', 'Lord Jesus, you called Matthew from collecting taxes to become your apostle and evangelist: Grant us the grace to forsake all covetous desires and inordinate love of riches, that we may follow you as he did and proclaim to the world around us the good news of your salvation; for with the Father and the Holy Spirit you live and reign, one God, now and for ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (203, 'collect', 'proper', 'Michael', 'Everlasting God, you have ordained and constituted in a wonderful order the ministries of angels and mortals: Mercifully grant that, as your holy angels always serve and worship you in heaven, so by your appointment they may help and defend us here on earth; through Jesus Christ our Lord, who lives and reigns with you and the Holy Spirit, one God, for ever and ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (204, 'collect', 'proper', 'Luke', 'Almighty God, you called your servant Luke to be an evangelist and physician of the soul: Grant that, by the wholesome medicine of the doctrine he taught, all the diseases of our souls may be healed; through Jesus Christ our Lord, who lives and reigns with you and the Holy Spirit, one God, now and for ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (205, 'collect', 'proper', 'JamesOfJerusalem', 'Grant, O God, that, following the example of your apostle James the Just, kinsman of our Lord, your Church may give itself continually to prayer and to the reconciliation of all who are at variance and enmity; through Jesus Christ our Lord, who lives and reigns with you and the Holy Spirit, one God, now and for ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (206, 'collect', 'proper', 'SimonJude', 'Grant, O God, that as your apostles Simon and Jude were faithful and zealous in their mission, so we may with ardent devotion make known the love and mercy of our Lord and Savior Jesus Christ; who lives and reigns with you and the Holy Spirit, one God, for ever and ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (207, 'collect', 'proper', 'AllSaints', 'Almighty God, you have knit together your elect in one communion and fellowship in the mystical Body of your Son: Give us grace so to follow your blessed saints in all virtuous and godly living, that we may come to those ineffable joys that you have prepared for those who truly love you; through Jesus Christ our Lord, who with you and the Holy Spirit lives and reigns, one God, in glory everlasting. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (208, 'collect', 'proper', 'Ember', 'Almighty God, the giver of all good gifts, in your divine providence you have appointed various orders in your Church: Give your grace, we humbly pray, to all who are \\[now\\] called to any office and ministry for your people; and so fill them with the truth of your doctrine and clothe them with holiness of life, that they may faithfully serve before you, to the glory of your great Name and for the benefit of your holy Church; through Jesus Christ our Lord, who lives and reigns with you, in the unity of the Holy Spirit, one God, now and for ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (209, 'collect', 'proper', 'Ember', 'O God, you led your holy apostles to ordain ministers in every place: Grant that your Church, under the guidance of the Holy Spirit, may choose suitable persons for the ministry of Word and Sacrament, and may uphold them in their work for the extension of your kingdom; through the great Shepherd and Bishop of our souls, Jesus Christ our Lord, who lives and reigns with you and the Holy Spirit, one God, for ever and ever. **Amen.**', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (210, 'collect', 'proper', 'Rogation', 'Almighty God, Lord of heaven and earth: We humbly pray that your gracious providence may give and preserve to our use the harvests of the land and of the seas, and may prosper all who labor to gather them, that we, who are constantly receiving good things from your hand, may always give you thanks; through Jesus Christ our Lord, who lives and reigns with you and the Holy Spirit, one God, for ever and ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (211, 'collect', 'proper', 'Rogation', 'Almighty God, whose Son Jesus Christ in his earthly life shared our toil and hallowed our labor: Be present with your people where they work; make those who carry on the industries and commerce of this land responsive to your will; and give us all a right satisfaction in what we do, and a just return for our labor; through Jesus Christ our Lord, who lives and reigns with you, in the unity of the Holy Spirit, one God, now and for ever. **Amen.**', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (212, 'collect', 'proper', 'Military', 'O King and Judge of the nations: We remember before you with grateful hearts the men and women of our armed forces, who in the day of decision ventured much for the liberties we now enjoy; grant that we may not rest until all the people of this land share the benefits of true freedom and gladly accept its disciplines; through Jesus Christ our Lord, who with you and the Holy Spirit lives and reigns, now and for ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (213, 'collect', 'proper', 'CanadaDay', 'Almighty God, whose wisdom and love are over all: Accept the prayers we offer for Canada, and give integrity to its citizens and wisdom to those in authority, that harmony and justice may be secured in obedience to your will; through Jesus Christ our Lord, who lives and reigns with you and the Holy Spirit, one God, for ever and ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (214, 'collect', 'proper', 'IndependenceDay', 'Lord God, by your providence our founders won their liberties of old: Grant that we and all the people of this land may have grace to exercise these liberties in righteousness and peace; through Jesus Christ our Lord, who lives and reigns with you and the Holy Spirit, one God, for ever and ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (215, 'collect', 'proper', 'Thanksgiving', 'Most merciful Father, we humbly thank you for all your gifts so freely bestowed upon us: for life and health and safety, for strength to work and leisure to rest, for all that is beautiful in creation and in human life; but above all we thank you for our spiritual mercies in Christ Jesus our Lord; who with you and the Holy Spirit lives and reigns, one God, for ever and ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (216, 'collect', 'proper', 'Martyr', 'Almighty God, you gave your servant *N.* boldness to confess the Name of our Savior Jesus Christ before the rulers of this world, and courage to die for this faith: Grant that we may always be ready to give a reason for the hope that is in us, and to suffer gladly for the sake of our Lord Jesus Christ; who lives and reigns with you and the Holy Spirit, one God, for ever and ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (217, 'collect', 'proper', 'MissionaryEvangelist', 'Almighty and everlasting God, you called your servant *N.* to preach the Gospel to the people of \\_\\_\\_\\_\\_\\_\\_\\_\\_ \\[*or* to the \\_\\_\\_\\_\\_\\_\\_\\_\\_ people\\]: Raise up in this and every land evangelists and heralds of your kingdom, that your Church may proclaim the unsearchable riches of our Savior Jesus Christ; who lives and reigns with you and the Holy Spirit, one God, now and for ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (218, 'collect', 'proper', 'Pastor', 'O God, our heavenly Father, you raised up your faithful servant *N.* to be a \\[Bishop and\\] pastor in your Church and to feed your flock: Give abundantly to all pastors the gifts of your Holy Spirit, that they may minister in your household as true servants of Christ and stewards of your divine mysteries; through Jesus Christ our Lord, who lives and reigns with you and the Holy Spirit, one God, for ever and ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (219, 'collect', 'proper', 'TeacherOfTheFaith', 'Almighty God, you gave your servant *N.* special gifts of grace to understand and teach the truth revealed in Christ Jesus: Grant that by this teaching we may know you, the one true God, and Jesus Christ whom you have sent; who lives and reigns with you and the Holy Spirit, one God, for ever and ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (220, 'collect', 'proper', 'Monastic', 'O God, your blessed Son became poor for our sake, and chose the Cross over the kingdoms of this world: Deliver us from an inordinate love of worldly things, that we, inspired by the devotion of your servant *N.*, may seek you with singleness of heart, behold your glory by faith, and attain to the riches of your everlasting kingdom, where we shall be united with our Savior Jesus Christ; who lives and reigns with you and the Holy Spirit, one God, now and for ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (221, 'collect', 'proper', 'Ecumenist', 'Almighty God, we give you thanks for the ministry of *N.*, who labored that the Church of Jesus Christ might be one: Grant that we, instructed by *his* teaching and example, and knit together in unity by your Spirit, may ever stand firm upon the one foundation, which is Jesus Christ our Lord; who lives and reigns with you, in the unity of the Holy Spirit, one God, now and for ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (222, 'collect', 'proper', 'ReformerOfTheChurch', 'O God, by your grace your servant *N.*, kindled by the flame of your love, became a burning and shining light in your Church, turning pride into humility and error into truth: Grant that we may be set aflame with the same spirit of love and discipline, and walk before you as children of light; through Jesus Christ our Lord, who lives and reigns with you, in the unity of the Holy Spirit, one God, now and for ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (223, 'collect', 'proper', 'RenewerOfSociety', 'Almighty and everlasting God, you kindled the flame of your love in the heart of your servant *N.* to manifest your compassion and mercy to the poor and the persecuted: Grant to us, your humble servants, a like faith and power of love, that we who give thanks for *his* righteous zeal may profit by *his* example; through Jesus Christ our Lord, who lives and reigns with you and the Holy Spirit, one God, for ever and ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (224, 'collect', 'proper', 'Commemoration', 'Almighty God, you have surrounded us with a great cloud of witnesses: Grant that we, encouraged by the good example of your servant *N.*, may persevere in running the race that is set before us, until at last, with *him*, we attain to your eternal joy; through Jesus Christ, the pioneer and perfecter of our faith, who lives and reigns with you and the Holy Spirit, one God, for ever and ever. **Amen.**', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO "texts" ("id", "type", "filter_type", "filter_content", "text", "title", "default_order", "detailed_title", "reading", "option_group", "optional", "book", "book_name", "reference_long", "reference_short", "note", "subcycles") VALUES (225, 'collect', 'proper', 'Commemoration', 'Almighty God, by your Holy Spirit you have made us one with your saints in heaven and on earth: Grant that in our earthly pilgrimage we may always be supported by this fellowship of love and prayer, and know ourselves to be surrounded by their witness to your power and mercy; for the sake of Jesus Christ, in whom all our intercessions are acceptable through the Spirit, and who lives and reigns with you and the same Spirit, one God, for ever and ever. **Amen.**', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
